/* Offline UI. Every imported string is treated as text; no network calls. */
(async function(){'use strict';
const L=HortiPlanning,C=HortiCore,P=HortiPrint,E=P.esc,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const online=globalThis.HortiOnline||null;
let onlineSeed=online?await online.start():null;const isGroup=online?.role==='group';
const FR=isGroup?[online.session.specialty]:C.specialties;
const blockedGroup=new Set(['backup','new-workshop','edit-workshop','save-workshop','invitation','choose-type','choose-specialty','save-pattern','new-task','edit-task','confirm-family','use-exam','save-use','export-exam','add-asset','download-source','download-asset','source','merge-project','open-project','choose-open-project','docx','choose-docx','open-session','close-session','approve-device','revoke-device']);
const forbidden=a=>isGroup&&blockedGroup.has(a)||online&&['open-project','choose-open-project'].includes(a);
let seed=onlineSeed||JSON.parse($('#seed').textContent),db=C.validate(seed),route='dashboard',workshopId=null,lastWorkshopId=null,examId=null,query='',fr='',type='',category='',kind='practical',quality='',year='',limit=24,dirty=false,storage=null,saveTimer,toastTimer,storageText='Browser-Speicher wird geprüft …',modalTask=null,modalMode=null,pendingAssets=[],importMode='merge';
const storageKey=seed.projectId;seed=null;onlineSeed=null;
const current=()=>db.exams.find(e=>e.id===examId),activeTasks=()=>db.tasks.filter(t=>!t.supersededBy&&(!type||t.examType===type)&&(!fr||t.specialty===fr)),family=id=>db.families.find(f=>f.id===id),source=id=>db.sources.find(s=>s.id===id),asset=id=>db.assets.find(a=>a.id===id);
const years=t=>[...new Set(t.sourceIds.map(id=>source(id)?.year).filter(Boolean))].sort();
const lastYear=t=>years(t).at(-1)||'–';
const solutionLabel=t=>t.solutionStatus==='approved'?'Lösung freigegeben':t.solutionStatus==='draft'?'Lösungsentwurf':'Lösung offen';
const num=(v,suffix='')=>v==null?'offen':v+suffix;
const options=(values,selected,first)=>`${first!==undefined?`<option value="">${E(first)}</option>`:''}${values.map(v=>`<option value="${E(v)}" ${v===selected?'selected':''}>${E(v)}</option>`).join('')}`;
const typeOptions=selected=>`<option value="ZP" ${selected==='ZP'?'selected':''}>Zwischenprüfung</option><option value="AP" ${selected==='AP'?'selected':''}>Abschlussprüfung</option>`;
const btn=(action,label,cls='',id='')=>forbidden(action)?'':`<button class="${cls}" data-action="${action}" ${id?`data-id="${E(id)}"`:''}>${label}</button>`;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function download(name,content,mime='application/json'){if(isGroup)throw Error('Exporte sind der zuständigen Stelle vorbehalten.');const blob=content instanceof Blob?content:new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function safeName(s){return (s||'Pruefung').replace(/[^a-zA-Z0-9äöüÄÖÜß_. -]/g,'_').slice(0,90);}
async function initStorage(){if(online){storageText='Zentral gespeichert';return;}if(document.querySelector('meta[name=hortiexam-storage]')?.content==='memory'){storage=null;storageText='Nur diese Sitzung · Projekt vor dem Schließen sichern';return;}try{storage=await new Promise((resolve,reject)=>{const r=indexedDB.open('hortiexam-offline-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Speicher blockiert'));});const saved=await new Promise((resolve,reject)=>{const t=storage.transaction('projects').objectStore('projects').get(storageKey);t.onsuccess=()=>resolve(t.result);t.onerror=()=>reject(t.error);});if(saved)db=C.validate(saved);storageText='Lokal im Browser · Backup empfohlen';}catch(e){storage=null;storageText='Nur Arbeitsspeicher · Datei sichern';toast('Browser-Speicher nicht verfügbar. Bitte Projektdatei regelmäßig sichern.');}}
let changeSerial=0,saving=null,saveError=null;
function changed(){dirty=true;changeSerial++;storageText=online?'Änderungen werden zentral gespeichert …':storage?'Änderungen werden lokal gespeichert …':'Nur Arbeitsspeicher · Datei sichern';clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(()=>{}),700);const el=$('#save-state');if(el)el.textContent=storageText;}
async function persist(){if(online){if(saving)return saving;if(!dirty)return;const serial=changeSerial,snapshot=C.clone(db);saving=(async()=>{try{await online.save(snapshot);if(serial===changeSerial)dirty=false;saveError=null;storageText=dirty?'Weitere Änderungen werden gespeichert …':'Zentral gespeichert · '+new Date().toLocaleTimeString('de-DE');}catch(e){saveError=e;storageText=e.status===409?'Speicherkonflikt · Abgleich erforderlich':'Nicht gespeichert · erneut versuchen';toast(e.message);if(e.status===409)render();throw e;}finally{saving=null;const el=$('#save-state');if(el)el.textContent=storageText;if(dirty&&!saveError)saveTimer=setTimeout(()=>persist().catch(()=>{}),150);}})();return saving;}if(!storage)return;try{await new Promise((resolve,reject)=>{const t=storage.transaction('projects','readwrite');t.objectStore('projects').put(db,storageKey);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});storageText='Lokal gespeichert · Backup empfohlen';}catch(e){storageText='Speichern fehlgeschlagen · Datei sichern';toast('Lokales Speichern fehlgeschlagen. Jetzt Projektdatei sichern.');}const el=$('#save-state');if(el)el.textContent=storageText;}
async function flush(){clearTimeout(saveTimer);if(saving)await saving;while(dirty)await persist();}
async function reloadCentral(){if(dirty&&!confirm('Noch nicht gespeicherte Änderungen gehen beim Neuladen verloren. Zentralen Stand trotzdem laden?'))return;clearTimeout(saveTimer);$('#app').inert=true;$('#dialog').inert=true;try{if(saving)await saving;clearTimeout(saveTimer);const next=await online.load();db=next;dirty=false;saveError=null;storageText='Zentraler Stand geladen';if(examId&&!current())examId=null;render();toast('Aktuelle Arbeitsstände geladen.');}finally{$('#app').inert=false;$('#dialog').inert=false;}}
async function backup(){if(online){await flush();await online.request('/api/export');}download(safeName(db.name)+'-'+new Date().toISOString().slice(0,10)+'.pruefbank.json',JSON.stringify(db));dirty=false;toast('Projektdatei heruntergeladen. Sie enthält Aufgaben, Anlagen und Prüfungen.');}
function openModal(title,body,footer=''){const dialog=$('#dialog');dialog.innerHTML=`<div class="modal-head"><h2>${E(title)}</h2>${btn('close','✕','ghost')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal();applyOnlineUI();}
function closeModal(){modalTask=null;modalMode=null;pendingAssets=[];$('#dialog').close();}
const meeting=()=>db.workshops.find(w=>w.id===workshopId);
const targetYear=()=>meeting()?.examYear||new Date().getFullYear()+1;
const scopedExams=()=>db.exams.filter(e=>e.examType===type&&e.specialty===fr&&(!workshopId||e.workshopId===workshopId));
function meetingPicker(){if(isGroup)return '';return db.workshops.length?`<div class="meeting-picker"><label for="meeting-select">Vorbereitungstermin</label><select id="meeting-select">${db.workshops.map(w=>`<option value="${E(w.id)}" ${w.id===workshopId?'selected':''}>${E(w.title)} · Prüfungsjahr ${w.examYear}</option>`).join('')}</select>${btn('edit-workshop','Termin bearbeiten','small')}${btn('new-workshop','+ Weiterer Termin','small')}</div>`:'';}
function workflowSteps(){return `<div class="workflow-steps" aria-label="Ablauf der Prüfungsvorbereitung">${[
 ['01','Termin vorbereiten','Prüfungsjahr und Fachrichtungen festlegen.','dashboard'],
 ['02','Gruppen einladen','Je Fachrichtung ein temporärer QR- oder Link-Zugang.','access'],
 ['03','Prüfungen erarbeiten','Zwischen- und Abschlussprüfung getrennt zusammenstellen.','groups'],
 ['04','Ergebnisse prüfen','Aufgaben, Punkte und Lösungen prüfen und exportieren.','results']
].map(([n,title,text,r])=>`<button data-route="${r}" class="workflow-step ${route===r?'selected':''}"><span class="step-number">${n}</span><strong>${title}</strong><span>${text}</span>${r==='access'&&!online?'<small>Zugänge noch nicht verfügbar</small>':''}</button>`).join('')}</div>`;}
function dashboardView(){const w=meeting(),es=w?C.workshopExams(db,w.id):[],ready=es.filter(e=>C.readiness(e).ready).length;return `<div class="dashboard-hero"><div><p class="eyebrow">Zuständige Stelle · Übersicht</p><h1>Gemeinsam die Prüfungen ${targetYear()} vorbereiten.</h1><p class="intro">Hier steuern Sie den Vorbereitungstermin: Arbeitsgruppen zusammenstellen, Zwischen- und Abschlussprüfungen erarbeiten und die fertigen Unterlagen prüfen.</p></div><span class="year-seal">Prüfungsjahr<strong>${targetYear()}</strong></span></div>${workflowSteps()}${meetingPicker()}${!w?`<div class="start-panel"><p class="eyebrow">Hier beginnen</p><h2>Vorbereitungstermin anlegen</h2><p>Legen Sie das Prüfungsjahr und die beteiligten Fachrichtungen fest. Jede Gruppe erhält einen Arbeitsbereich für beide Prüfungsarten.</p>${btn('new-workshop','1. Termin vorbereiten →','primary')}</div>`:`<div class="stats"><div class="stat highlight"><div class="stat-number">${w.specialties.length}</div><div class="stat-label">Fachrichtungsgruppen vorbereitet</div></div><div class="stat"><div class="stat-number">${es.filter(e=>e.examType==='ZP').length}</div><div class="stat-label">Zwischenprüfungsentwürfe</div></div><div class="stat"><div class="stat-number">${es.filter(e=>e.examType==='AP').length}</div><div class="stat-label">Abschlussprüfungsentwürfe</div></div><div class="stat"><div class="stat-number">${ready}</div><div class="stat-label">Prüfungen mit vollständigen Freigaben</div></div></div><div class="row between section-heading"><div><h2>Arbeitsgruppen für ${w.examYear}</h2><p class="muted">${E(w.title)} · Vorbereitung: ${w.meetingDate?E(w.meetingDate.split('-').reverse().join('.')):'Datum noch offen'}</p></div><button data-route="access">Gruppen & Einladungen →</button></div>${groupCards()}`}<div class="utility-grid"><button data-route="scope"><strong>Aufgabenbestand & Muster</strong><span>Fachrichtungen, Kategorien, Familien und Varianten pflegen →</span></button><button data-route="import"><strong>Alte Prüfungen einlesen</strong><span>Word-Dateien, Quellen und vorhandene Projekte ergänzen →</span></button><button data-route="results"><strong>Alle Prüfungsergebnisse</strong><span>Entwürfe öffnen, Lösungen prüfen und Unterlagen exportieren →</span></button></div>`;}
function groupCards(){const w=meeting();if(!w)return '<div class="panel"><h2>Zuerst einen Termin vorbereiten</h2><p>Danach erscheinen hier die Fachrichtungsgruppen mit ihren beiden Prüfungsarten.</p>'+btn('new-workshop','Termin vorbereiten','primary')+'</div>';return `<div class="group-grid">${w.specialties.map(s=>{const es=C.workshopExams(db,w.id,s);return `<article class="group-card"><span class="badge gray">${online?accessStatus(w.id):'Zugang noch nicht eingerichtet'}</span><h3>${E(s)}</h3><div class="group-track-summary"><span><b>${es.filter(e=>e.examType==='ZP').length}</b> Zwischenprüfung</span><span><b>${es.filter(e=>e.examType==='AP').length}</b> Abschlussprüfung</span></div>${btn('open-group','Arbeitsbereich öffnen →','primary wide',s)}${btn('invitation','QR-Code & Zugang','ghost wide',s)}</article>`;}).join('')}</div>`;}
function groupsView(){return `<p class="eyebrow">3 · Prüfungen erarbeiten</p><h1>Arbeitsbereiche der Fachrichtungen</h1><p class="intro">Jede Fachrichtung arbeitet an ihren Zwischen- und Abschlussprüfungen. Sie öffnen die Arbeitsbereiche hier als zuständige Stelle.</p>${meetingPicker()}${groupCards()}`;}
function groupView(){const w=meeting();if(!w||!w.specialties.includes(fr))return groupsView();const es=C.workshopExams(db,w.id,fr);return `<p class="eyebrow">Arbeitsgruppe · Prüfungsjahr ${w.examYear}</p><h1>${E(fr)}</h1><p class="intro">Welche Prüfung möchten Sie vorbereiten? Aufgabenbank, Prüfungsmuster und Entwürfe bleiben nach Prüfungsart getrennt.</p><div class="toolbar">${isGroup?'':'<button data-route="groups">← Alle Arbeitsgruppen</button>'}${btn('invitation','QR-Code & Zugang','',fr)}<span class="badge gray">${isGroup?'Arbeitsgruppe · Entwürfe werden zentral gespeichert':'Ansicht der zuständigen Stelle'}</span></div><div class="exam-tracks">${['ZP','AP'].map(t=>{const p=L.pattern(db,t,fr),tasks=L.scoped(db,t,fr),drafts=es.filter(e=>e.examType===t);return `<section class="exam-track"><span class="badge ${t==='AP'?'blue':''}">${t}</span><h2>${t==='ZP'?'Zwischenprüfung':'Abschlussprüfung'} ${w.examYear}</h2><p class="tiny">${tasks.length} Aufgabenvarianten · ${p.status==='confirmed'?'Prüfungsmuster bestätigt':'Prüfungsmuster noch prüfen'}</p><ol class="track-guide"><li>Pflichtkategorien prüfen</li><li>Aufgaben auswählen und anpassen</li><li>Prüfung und Lösung kontrollieren</li></ol><div class="toolbar">${btn('track-pattern','1. Muster prüfen','',t)}${btn('track-new','+ Prüfung erstellen','primary',t)}</div>${drafts.length?drafts.map(e=>`<div class="draft-line"><div><strong>${E(e.title)}</strong><span class="tiny">${e.items.length} Aufgaben · ${C.readiness(e).ready?'Freigaben vollständig':'Bearbeitung offen'}</span></div>${btn('select-exam','Weiterarbeiten →','small',e.id)}</div>`).join(''):'<p class="empty-track">Noch kein Entwurf. Starten Sie mit dem Prüfungsmuster.</p>'}${!tasks.length?'<p class="callout warning">Für diese Prüfungsart fehlen noch Aufgaben. Sie können Unterlagen importieren oder eigene Aufgaben anlegen.</p>':''}</section>`;}).join('')}</div>`;}
function workshopForm(edit=false){const w=edit?meeting():null;openModal(w?'Vorbereitungstermin bearbeiten':'Vorbereitungstermin anlegen',`<p class="intro">Der Vorbereitungstermin ist das Treffen der Arbeitsgruppen. Das Prüfungsjahr bezeichnet die späteren Prüfungen.</p><div class="field"><label for="workshop-title">Name des Vorbereitungstermins</label><input id="workshop-title" value="${E(w?.title||'Aufgabenerstellung '+(new Date().getFullYear()+1))}"></div><div class="grid2"><div class="field"><label for="workshop-year">Prüfungsjahr</label><input id="workshop-year" type="number" min="1900" max="2200" step="1" value="${w?.examYear||new Date().getFullYear()+1}"></div><div class="field"><label for="workshop-date">Vorbereitungstermin (optional)</label><input id="workshop-date" type="date" value="${E(w?.meetingDate||'')}"></div></div><h3>Beteiligte Fachrichtungsgruppen</h3><div class="category-checks">${FR.map(s=>`<label class="check"><input type="checkbox" data-workshop-specialty value="${E(s)}" ${!w||w.specialties.includes(s)?'checked':''}>${E(s)}</label>`).join('')}</div><p class="tiny">Jede Gruppe kann mehrere Zwischen- und Abschlussprüfungen erstellen. Das Speichern bereitet die Arbeitsbereiche vor; es aktiviert noch keine externen Zugänge.</p>`,btn('close','Abbrechen')+btn('save-workshop',w?'Änderungen speichern':'Termin & Arbeitsbereiche anlegen','primary',w?.id||''));}
function saveWorkshop(id){const w={id:id||C.id('workshop'),title:$('#workshop-title').value.trim(),examYear:Number($('#workshop-year').value),meetingDate:$('#workshop-date').value,specialties:$$('[data-workshop-specialty]:checked').map(x=>x.value)};C.saveWorkshop(db,w);workshopId=w.id;examId=null;type=fr=category='';route='dashboard';changed();closeModal();render();toast('Vorbereitungstermin gespeichert. Die Arbeitsbereiche sind vorbereitet.');}
function invitation(s){if(online)return showInvitation(s);const w=meeting();if(!w)throw Error('Bitte zuerst einen Vorbereitungstermin anlegen.');openModal('Gruppenzugang · '+s,`<p class="eyebrow">${E(w.title)} · Prüfungsjahr ${w.examYear}</p><div class="invitation-state"><span aria-hidden="true">⌁</span><h2>QR-Code noch nicht verfügbar</h2><p>Ein sicherer Gruppenzugang kann erst erstellt werden, wenn der Anmeldedienst angeschlossen ist.</p></div><div class="callout warning"><strong>Noch keine Einladung versenden</strong>Das Passwort der zuständigen Stelle öffnet den gesamten Bestand. Es darf nicht als Gruppenpasswort oder QR-Code verteilt werden.</div><h3>So soll der Zugang anschließend funktionieren</h3><ol class="track-guide"><li>Sie geben die Sitzung frei und zeigen den QR-Code oder teilen den Gruppenlink.</li><li>Die Gruppe landet direkt bei ${E(s)} mit Zwischen- und Abschlussprüfung ${w.examYear}.</li><li>Sie schließen die Sitzung; weitere Zugriffe werden serverseitig gesperrt.</li></ol><p class="tiny">Freigabe, Ablauf und Exportrechte sind in dieser Testversion noch nicht durchgesetzt. Bereits angefertigte Kopien oder Bildschirmaufnahmen lassen sich nicht zurückholen.</p>`,btn('close','Schließen')+'<button disabled>QR-Code anzeigen / Link kopieren</button>');}
function resultsView(){const w=meeting(),es=w?C.workshopExams(db,w.id):[],others=db.exams.filter(e=>!w||e.workshopId!==w.id);return `<p class="eyebrow">4 · Ergebnisse prüfen</p><h1>Prüfungen & Ergebnisse</h1><p class="intro">Öffnen Sie einen Entwurf, kontrollieren Sie Kategorien, Punkte und Lösungen und erstellen Sie anschließend die Teilnehmer- und Prüferfassung.</p>${meetingPicker()}${w?`<h2>${E(w.title)} · ${w.examYear}</h2>${resultRows(es)}`:''}${others.length?`<h2 class="section-title">${w?'Weitere und bisherige Prüfungen':'Alle bisherigen Prüfungen'}</h2>${resultRows(others)}`:!w?'<div class="panel empty">Noch keine Prüfungen vorhanden. Beginnen Sie auf der Übersicht mit einem Vorbereitungstermin.</div>':''}`;}
function resultRows(es){return es.length?es.map(e=>{const r=C.readiness(e),w=db.workshops.find(w=>w.id===e.workshopId);return `<article class="result-row panel"><div><div class="tags"><span class="badge ${e.examType==='AP'?'blue':''}">${e.examType==='AP'?'Abschlussprüfung':'Zwischenprüfung'}</span><span class="badge ${r.ready?'':'amber'}">${e.status==='used'?'Einsatz dokumentiert':r.ready?'Freigaben vollständig':'Bearbeitung offen'}</span></div><h3>${E(e.title)}</h3><p class="tiny">${E(e.specialty)} · ${e.examYear||'Prüfungsjahr offen'} · ${e.items.length} Aufgaben · ${E(w?.title||'Noch keinem Vorbereitungstermin zugeordnet')}</p></div>${btn('select-exam','Prüfen / weiterarbeiten →','primary',e.id)}</article>`;}).join(''):'<div class="panel empty">Für diesen Vorbereitungstermin wurden noch keine Prüfungen angelegt. Öffnen Sie einen Fachrichtungsbereich unter „Arbeitsgruppen“.</div>';}

function scopeView(){return `<p class="eyebrow">1 · Prüfungsbereich wählen</p><h1>Welche Prüfung bereiten wir vor?</h1><p class="intro">Zwischenprüfung und Abschlussprüfung haben eigene Aufgabenbereiche und Prüfungsmuster.</p><div class="scope-types">${[['ZP','Zwischenprüfung','Grundlegende praktische Fertigkeiten'],['AP','Abschlussprüfung','Fachrichtungsbezogene Arbeitsaufgaben']].map(([id,title,sub])=>`<button class="scope-choice ${type===id?'selected':''}" data-action="choose-type" data-id="${id}"><span class="eyebrow">${id}</span><h2>${title}</h2><p>${sub}</p><strong>${L.scoped(db,id,fr||FR[0]).length? 'Prüfungsbereich öffnen →':'Fachrichtung wählen →'}</strong></button>`).join('')}</div>${type?`<h2 class="section-title">Fachrichtung der ${type==='AP'?'Abschlussprüfung':'Zwischenprüfung'}</h2><div class="cards">${FR.map(s=>{const ts=L.scoped(db,type,s);return `<button class="scope-choice" data-action="choose-specialty" data-id="${E(s)}"><h3>${E(s)}</h3><p>${ts.length} praktische Varianten · ${new Set(ts.map(t=>t.familyId)).size} Aufgabenfamilien</p><span class="tiny">${ts.length?'Prüfungsmuster und Kategorien ansehen →':'Noch kein praktischer Aufgabenbestand vorhanden'}</span></button>`;}).join('')}</div>`:''}<div class="callout warning"><strong>Planungstest für die zuständige Stelle</strong>GitHub Pages bietet hier noch keine getrennten Prüferkonten. Diesen Zugang nicht als temporären Prüferzugang verteilen. Exporte bleiben der Koordination vorbehalten; Offline-Satelliten werden nicht mehr erzeugt.</div>`;}
function scopeHeading(step){return `<p class="eyebrow">${step} · ${type==='AP'?'Abschlussprüfung':'Zwischenprüfung'}</p><h1>${E(fr)}</h1><div class="toolbar"><span class="badge ${type==='AP'?'blue':''}">${type==='AP'?'Abschlussprüfung':'Zwischenprüfung'}</span>${btn('all-categories','Kategorien & Aufgaben','small')}<button class="small ghost" data-route="scope">Prüfungsbereich wechseln</button></div>`;}
function historyText(h){return h.unknown?'Nutzung unbekannt · vor Auswahl prüfen':`${h.confirmed?'Bestätigter Einsatz: '+h.confirmed:'Kein bestätigter Einsatztermin'}${h.sourceYear?' · jüngstes Quelldokument: '+h.sourceYear:''}`;}
function patternView(){const p=L.pattern(db,type,fr),tasks=L.scoped(db,type,fr),unknown=tasks.filter(t=>L.classify(t).ids.includes('unassigned')).length;return `${scopeHeading('2 · Prüfungsmuster')}<p class="intro">Das bestätigte Muster legt fest, wie viele Aufgaben jede Kategorie abdecken müssen. Neue Prüfungen übernehmen eine feste Kopie dieses Musters.</p><div class="callout ${p.status==='confirmed'?'':'warning'}"><strong>${p.status==='confirmed'?'Arbeitsmuster bestätigt':'Vorschlag aus dem vorhandenen Archiv'}</strong>${E(p.note||'')} ${unknown?`${unknown} Aufgaben haben noch keine eindeutige Kategorie.`:''}</div><div class="panel"><div class="row between"><h2>Pflichtkategorien</h2><span class="badge">${type} · Version ${E(String(p.version||1))}</span></div><p class="tiny">0 = nicht Bestandteil des Musters. Kombinationsaufgaben können mehrere Kategorien zugleich abdecken. Anzahl und Vollständigkeit fachlich prüfen.</p>${L.catalog.map(c=>{const ts=tasks.filter(t=>L.classify(t).ids.includes(c.id)),slot=p.slots.find(s=>s.categoryId===c.id),ys=[...new Set(ts.flatMap(years))].sort();return `<div class="pattern-row"><div><strong>${E(c.label)}</strong><p class="tiny">${ts.length} Varianten · ${new Set(ts.map(t=>t.familyId)).size} Familien · Quelljahre: ${ys.join(', ')||'keine Belege im Bestand'}</p></div><label>Anzahl<input data-slot-count="${c.id}" aria-label="Anzahl ${E(c.label)}" type="number" min="0" max="10" step="1" value="${slot?.count||0}"></label></div>`;}).join('')}<div class="field"><label for="pattern-note">Hinweise zum Prüfungsmuster</label><textarea id="pattern-note">${E(p.note||'')}</textarea></div><div class="field"><label for="pattern-reviewer">Bestätigt durch (Name oder Kürzel)</label><input id="pattern-reviewer" value="${E(p.reviewedBy||'')}"></div><label class="check"><input id="pattern-confirm" type="checkbox" ${p.status==='confirmed'?'checked':''}>Die Pflichtkategorien und Anzahlen sind als Arbeitsgrundlage bestätigt.</label><div class="toolbar">${btn('save-pattern','Prüfungsmuster speichern','primary')}${btn('new-exam','Neue Prüfung nach diesem Muster')}</div></div>`;}
function savePattern(){const previous=L.pattern(db,type,fr),slots=$$('[data-slot-count]').map(x=>({categoryId:x.dataset.slotCount,count:Number(x.value)})).filter(x=>x.count!==0),confirmed=$('#pattern-confirm').checked,reviewedBy=$('#pattern-reviewer').value.trim();if(confirmed&&!reviewedBy)throw Error('Bitte Name oder Kürzel für die Musterbestätigung eintragen.');const p={...C.clone(previous),id:`pattern:${type}:${fr}`,examType:type,specialty:fr,slots,status:confirmed?'confirmed':'proposed',reviewedBy,note:$('#pattern-note').value.trim(),version:(previous.version||0)+1,updatedAt:C.now()};L.checkPattern(p);db.patterns=db.patterns.filter(x=>!(x.examType===type&&x.specialty===fr));db.patterns.push(p);changed();render();toast('Muster gespeichert. Bestehende Prüfungen behalten ihren bisherigen Musterstand.');}
function bankView(){const tasks=L.scoped(db,type,fr),cats=[...L.catalog,{id:'unassigned',label:'Zuordnung offen'}].filter(c=>tasks.some(t=>L.classify(t).ids.includes(c.id))),results=filtered().filter(t=>t.kind==='practical');if(!category)return `${scopeHeading('3 · Kategorien')}<p class="intro">Kategorie öffnen, Aufgabenfamilien vergleichen und eine Variante wählen. Die Reihenfolge der Vorschläge berücksichtigt die jüngsten Belege der gesamten Familie.</p><div class="cards category-cards">${cats.map(c=>{const ts=tasks.filter(t=>L.classify(t).ids.includes(c.id)),slot=L.pattern(db,type,fr).slots.find(s=>s.categoryId===c.id);return `<button class="scope-choice" data-action="choose-category" data-id="${c.id}"><span class="badge ${c.id==='unassigned'?'amber':''}">${slot?slot.count+' im Muster':'Nicht im Muster'}</span><h3>${E(c.label)}</h3><p>${new Set(ts.map(t=>t.familyId)).size} Familien · ${ts.length} Varianten</p><strong>Aufgaben auswählen →</strong></button>`;}).join('')}</div>${!tasks.length?'<div class="panel">Für diesen Bereich fehlen praktische Aufgaben. Über Import & Quellen weitere Unterlagen ergänzen.</div>':''}`;
 const ordering=L.rank(db,type,fr,category),familyIds=[...new Set(ordering.filter(r=>results.some(t=>t.id===r.task.id)).map(r=>r.task.familyId))];return `${scopeHeading('3 · Aufgaben auswählen')}<h2>${E(L.label(category))}</h2><p class="intro">Ältere Familienbelege stehen zuerst. Unbekannte Nutzung steht separat am Ende und bedeutet nicht „noch nie verwendet“.</p><div class="toolbar"><div class="search"><input id="search" type="search" aria-label="Aufgaben suchen" placeholder="Innerhalb dieser Kategorie suchen …" value="${E(query)}"></div>${btn('new-task','+ Eigene Aufgabe')}</div><div class="result-bar"><span>${results.length} Varianten in ${familyIds.length} Familien</span><span>Quelljahr ≠ bestätigter Einsatz</span></div>${familyIds.map(id=>{const ts=ordering.filter(r=>r.task.familyId===id&&results.some(t=>t.id===r.task.id)),h=ts[0].history;return `<section class="family-group"><div class="row between"><div><p class="eyebrow">Aufgabenfamilie · ${ts.length} Varianten</p><h2>${E(family(id)?.title||ts[0].task.title)}</h2><p class="tiny">${E(historyText(h))}</p></div>${btn('family','Varianten vergleichen','small',id)}</div><div class="cards">${ts.map(r=>card(r.task)).join('')}</div></section>`;}).join('')}${!familyIds.length?'<div class="empty">Keine passenden Aufgaben in dieser Kategorie.</div>':''}`;}
function coverageView(e){const c=L.coverage(e);return `<div class="coverage"><div class="row between"><strong>Kategorien im Entwurf</strong><span class="badge ${c.complete?'':'amber'}">${c.complete?'vollständig':'offen'}</span></div>${c.slots.map(s=>`<button class="coverage-row ${s.actual===s.count?'complete':''}" data-action="choose-category" data-id="${s.categoryId}"><span>${E(L.label(s.categoryId))}</span><strong>${s.actual}/${s.count}</strong></button>`).join('')}<p class="tiny">${c.issues.length?E(c.issues.join(' ')):'Alle Pflichtkategorien sind passend besetzt.'}</p>${btn('suggest','Rotationsvorschläge ansehen','primary wide')}${btn('apply-pattern','Aktuelles Muster übernehmen','ghost small')}</div>`;}
let proposedTasks=[];
function suggestTasks(){const e=current();if(!e)throw Error('Bitte zuerst eine Prüfung anlegen.');if(e.status==='used')throw Error('Bereits eingesetzte Prüfung zuerst duplizieren.');proposedTasks=L.propose(db,e);const draft=C.clone(e);proposedTasks.forEach(t=>C.addItem(draft,t));const c=L.coverage(draft);openModal('Vorschläge für fehlende Kategorien',`<p class="intro">Pro Familie wird eine Variante vorgeschlagen. Aufgaben und Lösungen müssen weiterhin fachlich geprüft werden.</p>${proposedTasks.map(t=>`<div class="panel"><h3>${E(t.title)}</h3><p>${L.classify(t).ids.map(L.label).map(E).join(' · ')}</p><p class="tiny">${E(historyText(L.history(db,t)))}</p></div>`).join('')||'<p>Keine weiteren Vorschläge gefunden. Pflichtkategorien prüfen oder andere Aufgaben ergänzen.</p>'}${c.issues.length?`<div class="callout warning"><strong>Nach Übernahme noch zu klären</strong>${E(c.issues.join(' '))}</div>`:''}`,`${btn('close','Abbrechen')}${proposedTasks.length?btn('accept-suggestions',proposedTasks.length+' Vorschläge übernehmen','primary'):''}`);}
function acceptSuggestions(){const e=editableExam();for(const t of proposedTasks)if(!e.items.some(i=>i.task.familyId===t.familyId))C.addItem(e,t);proposedTasks=[];changed();closeModal();render();}
function categoryFields(t){const c=L.classify(t);return `<h3 class="section-title">Prüfungskategorien</h3><p class="tiny">${c.manual?'Manuell zugeordnet':'Vorschlag aus Aufgabenkopf'}: ${E(c.evidence.slice(0,300))}</p><div class="category-checks">${L.catalog.map(x=>`<label class="check"><input type="checkbox" data-planning-category value="${x.id}" ${c.ids.includes(x.id)?'checked':''}>${E(x.label)}</label>`).join('')}</div><p class="tiny">Bei einer Kombinationsaufgabe alle tatsächlich abgedeckten Kategorien auswählen.</p>`;}
function accessStatus(id){const a=online.board.meetings.find(a=>a.meeting_id===id);return a?.active&&a.expires>Date.now()?'Freigegeben bis '+new Date(a.expires).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}):'Sitzung geschlossen';}
function onlineAccessView(){const w=meeting(),requests=online.board.requests.filter(r=>r.meeting_id===w?.id);return `<p class="eyebrow">2 · Gruppen einladen</p><h1>Zugänge für den Vorbereitungstermin</h1><p class="intro">Sitzung freigeben, Gruppen-QR-Code zeigen und jedes beitretende Gerät anhand seines Codes bestätigen. Die Gruppe öffnet direkt ihren Arbeitsbereich.</p>${meetingPicker()}${w?`<div class="panel"><h2>${E(w.title)}</h2><p><strong>${E(accessStatus(w.id))}</strong></p><div class="toolbar">${btn('open-session','Sitzung freigeben / neue Links','primary')}${btn('close-session','Alle Gruppenzugänge schließen','danger')}${btn('refresh-access','Beitritte aktualisieren')}</div><p class="tiny">Neue Links ersetzen alte Einladungen und melden bereits verbundene Gruppen ab. Ein Gerätebeitritt muss erneut bestätigt werden.</p></div><h2>Geräte & Beitrittsanfragen</h2><p class="tiny">Vergleichen Sie den angezeigten Code mit dem Gerät der Gruppe, bevor Sie den Beitritt freigeben.</p>${requests.length?requests.map(r=>`<article class="panel row between"><div><strong>${E(r.label)}</strong><p>${E(r.specialty)} · Gerätecode <b>${E(r.code)}</b></p><span class="badge ${r.status==='pending'?'amber':''}">${r.status==='pending'?'Wartet auf Bestätigung':'Zugang aktiv'}</span></div><div class="toolbar">${r.status==='pending'?btn('approve-device','Gerät bestätigen','primary',r.id):''}${btn('revoke-device',r.status==='pending'?'Ablehnen':'Gerät sperren','danger',r.id)}</div></article>`).join(''):'<div class="panel">Noch keine aktiven Geräte oder offenen Beitrittsanfragen.</div>'}${groupCards()}`:groupCards()}`;}
async function openSession(){const w=meeting();if(!w)throw Error('Bitte zuerst einen Vorbereitungstermin anlegen.');await flush();openModal('Sitzung freigeben',`<p>${E(w.title)}</p><p>Wie lange dürfen die Arbeitsgruppen arbeiten?</p><div class="field"><label for="session-hours">Dauer ab jetzt</label><select id="session-hours"><option value="2">2 Stunden</option><option value="4" selected>4 Stunden</option><option value="8">8 Stunden</option><option value="12">12 Stunden</option></select></div><p class="callout warning">Die Freigabe erzeugt neue Gruppenlinks. Bisherige Links und bereits angemeldete Gruppengeräte werden dabei gesperrt.</p>`,btn('close','Abbrechen')+'<button id="confirm-open" class="primary">Neue Gruppenzugänge aktivieren</button>');$('#confirm-open').onclick=async()=>{const b=$('#confirm-open');b.disabled=true;try{await online.open(w.id,Date.now()+Number($('#session-hours').value)*3600000);closeModal();route='access';render();toast('Sitzung freigegeben. Jetzt je Fachrichtung den QR-Code anzeigen.');}catch(e){b.disabled=false;toast(e.message);}};}
async function closeSession(){const w=meeting();if(!w)return;if(!confirm('Alle Gruppenzugänge dieses Termins jetzt schließen? Bereits gespeicherte Entwürfe bleiben erhalten.'))return;await online.close(w.id);render();toast('Gruppenzugänge gesperrt. Weitere Datenanfragen werden abgewiesen.');}
async function decideDevice(id,approved){await online.request('/api/access/'+(approved?'approve':'revoke'),{requestId:id});await online.access();render();toast(approved?'Gerät freigegeben.':'Gerät gesperrt.');}
function showInvitation(s){const w=meeting();if(!w)throw Error('Bitte zuerst einen Vorbereitungstermin anlegen.');const link=online.link(w.id,s),active=online.board.meetings.some(a=>a.meeting_id===w.id&&a.active&&a.expires>Date.now());if(!link||!active){openModal('Gruppenzugang · '+s,`<p>Für diese Fachrichtung ist in diesem Browser noch kein gültiger Einladungslink vorhanden.</p><p>Öffnen Sie unter „Gruppen & Einladungen“ die Sitzung. Nach einer erneuten Anmeldung müssen neue Links erzeugt werden; bestehende Gruppen werden dabei abgemeldet.</p>`,btn('close','Schließen'));return;}openModal('Gruppenzugang · '+s,`<p class="eyebrow">${E(w.title)} · Prüfungsjahr ${w.examYear}</p><div class="qr-code">${online.qr(link)}</div><label for="invitation-link">Gruppenlink</label><input id="invitation-link" readonly value="${E(link)}"><p>1. QR-Code scannen oder Link öffnen.<br>2. Name / Gerät eintragen.<br>3. Gerätecode mit der zuständigen Stelle abgleichen.</p><p class="tiny">${E(accessStatus(w.id))}. Der Link allein erteilt noch keinen Datenzugriff.</p>`,btn('close','Schließen')+btn('copy-invitation','Link kopieren','primary'));}
async function copyInvitation(){const input=$('#invitation-link');try{await navigator.clipboard.writeText(input.value);toast('Gruppenlink kopiert.');}catch{input.focus();input.select();toast('Bitte den markierten Gruppenlink kopieren.');}}
function applyOnlineUI(){if(!online)return;if(isGroup){for(const x of $$('[data-route="scope"],[data-route="groups"]'))x.remove();for(const x of $$('[data-action]'))if(forbidden(x.dataset.action))x.remove();for(const x of $$('[data-slot-count],#pattern-note,#pattern-reviewer,#pattern-confirm,#task-fr,#task-type,#task-kind,#task-family,#task-review,#task-solution-status,#task-reviewer,#exam-fr,#exam-workshop,#exam-year'))x.disabled=true;for(const x of $$('[data-asset-audience] option[value="source"]'))x.remove();for(const x of $$('a[download]'))x.remove();}for(const el of $$('.callout')){if(el.textContent.includes('Planungstest für die zuständige Stelle'))el.innerHTML='<strong>Zentrale Aufgabenbank</strong>Arbeitsgruppen erhalten zeitlich begrenzte Zugänge für ihre Fachrichtung. Prüfungsmuster, fachliche Freigaben und Exporte verwaltet die zuständige Stelle.';if(el.textContent.includes('Koordinationstest, kein abgesicherter Prüferbetrieb'))el.innerHTML='<strong>Online zusammenarbeiten</strong>Arbeitsstände werden zentral gespeichert. Unter „Gruppen & Einladungen“ öffnen und schließen Sie die Sitzung und bestätigen einzelne Geräte. Bereits angefertigte Kopien oder Bildschirmaufnahmen lassen sich technisch nicht zurückholen.';}}

function accessView(){if(online)return onlineAccessView();return `<p class="eyebrow">2 · Gruppen einladen</p><h1>Gruppen & Einladungen</h1><p class="intro">Hier sollen Sie die Sitzung freigeben und je Fachrichtung den QR-Code anzeigen oder den Einladungslink teilen können. Jede Gruppe erhält ihren eigenen Arbeitsbereich für beide Prüfungsarten.</p>${meetingPicker()}<div class="callout warning"><strong>Temporäre Gruppenzugänge noch nicht eingerichtet</strong>Der sichere Anmeldedienst fehlt noch. Daher können aktuell keine QR-Codes, Gruppenlinks oder zeitlichen Freigaben erzeugt werden. Die Arbeitsbereiche können Sie bereits als zuständige Stelle vorbereiten.</div>${meeting()?`<div class="panel"><div class="row between"><div><h2>${E(meeting().title)}</h2><p class="tiny">Sitzung: nicht freigegeben · Prüfungsjahr ${meeting().examYear}</p></div><button disabled>Sitzung freigeben</button></div><p class="tiny">Nach Anschluss des Anmeldedienstes: öffnen, Ablaufzeit festlegen und alle Gruppenzugänge wieder schließen.</p></div>`:''}${groupCards()}`;}

function render(){if(isGroup&&!['group','patterns','bank','families','exams'].includes(route))route='group';if(['dashboard','groups','access','results'].includes(route)&&!meeting())workshopId=db.workshops.find(w=>w.id===lastWorkshopId)?.id||db.workshops[0]?.id||null;if(meeting())lastWorkshopId=workshopId;const labels={dashboard:'Übersicht',groups:'Arbeitsgruppen',group:'Arbeitsbereich',results:'Prüfungen & Ergebnisse',scope:'Aufgabenbestand & Muster',patterns:'Prüfungsmuster',bank:'Aufgabenbank',families:'Familien & Varianten',exams:'Prüfungsentwürfe',import:'Import & Quellen',access:'Gruppen & Einladungen',about:'Hinweise & Migration'};const editing=['patterns','bank','families','exams'].includes(route)&&type&&fr;$('#app').innerHTML=`<div class="shell"><aside class="nav"><div><div class="brand">Horti<span>Exam</span></div><div class="brand-sub">${isGroup?'ARBEITSGRUPPE':'ZUSTÄNDIGE STELLE'}</div></div>${(isGroup?[['group','▥']]:[['dashboard','⌂'],['access','♧'],['groups','▥'],['results','▤'],['scope','▦'],['import','↥']]).map(([r,i])=>`<button data-route="${r}" class="${route===r||(r==='groups'&&route==='group')||(r==='scope'&&editing)?'active':''}"><span class="nav-icon">${i}</span>${labels[r]}</button>`).join('')}<div class="nav-footer"><p><span class="dot"></span>${online?(isGroup?'Temporärer Gruppenzugang':'Zuständige Stelle · Online'):'Zuständige Stelle · Testversion'}</p><p>Praktischer Gartenbau<br>Zwischen- & Abschlussprüfung</p>${isGroup?'':'<button data-route="about">Hinweise & Migration ↗</button>'}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="ghost small" data-route="${isGroup?'group':'dashboard'}">${isGroup?'Arbeitsbereich':'Übersicht'}</button> / <strong>${labels[route]}</strong></div><div class="top-actions"><span class="save-state" id="save-state">${E(storageText)}</span>${online?(saveError?.status===409?btn('save-conflict-copy','Entwürfe als Kopie sichern','primary'):'')+btn('save-online','Speichern')+btn('reload-online','Aktualisieren')+btn('logout','Abmelden'):''}${btn('backup','↓ Projekt sichern')}${btn('new-workshop','+ Vorbereitungstermin','primary')}</div></header>${editing?`<div class="editor-context"><div><button data-route="${meeting()?'group':'scope'}" class="small">← ${meeting()?'Arbeitsgruppe':'Prüfungsbereich'}</button><strong>${E(fr)} · ${type==='ZP'?'Zwischenprüfung':'Abschlussprüfung'}${meeting()?' '+meeting().examYear:''}</strong></div><div class="toolbar"><button data-route="patterns" class="${route==='patterns'?'primary':''}">1. Muster</button><button data-route="bank" class="${route==='bank'?'primary':''}">2. Aufgaben</button><button data-route="exams" class="${route==='exams'?'primary':''}">3. Entwürfe</button><button data-route="families">Familien & Varianten</button></div></div>`:''}<div class="main-grid ${editing?'':'full-width'}"><main class="content">${route==='dashboard'?dashboardView():route==='groups'?groupsView():route==='group'?groupView():route==='results'?resultsView():route==='scope'?scopeView():route==='patterns'?patternView():route==='bank'?bankView():route==='families'?familiesView():route==='exams'?examsView():route==='import'?importView():route==='access'?accessView():aboutView()}</main>${editing?drawerView():''}</div></div></div>`;wireInputs();applyOnlineUI();const picker=$('#meeting-select');if(picker)picker.addEventListener('change',()=>{workshopId=picker.value;examId=null;fr=type=category='';render();});}

function filtered(){const q=query.toLocaleLowerCase('de');return activeTasks().filter(t=>(!fr||t.specialty===fr)&&(!type||t.examType===type)&&(!category||L.classify(t).ids.includes(category))&&(!kind||t.kind===kind)&&(!year||years(t).includes(Number(year)))&&(!quality||(quality==='solution'?t.solutionStatus!=='approved':quality==='flags'?t.flags.length:t.reviewStatus!=='approved'))&&(!q||[t.title,t.text,t.category,t.tags.join(' '),family(t.familyId)?.title,t.qualification].join(' ').toLocaleLowerCase('de').includes(q)));}
function card(t){const variants=activeTasks().filter(v=>v.familyId===t.familyId).length;return `<article class="card" draggable="true" data-drag-task="${E(t.id)}"><div class="card-top"><span class="badge ${t.examType==='AP'?'blue':''}">${E(t.examType)} · ${E(t.specialty==='Garten- und Landschaftsbau'?'GaLaBau':t.specialty)}</span><span class="tiny">${lastYear(t)}</span></div><h3>${E(t.title)}</h3><p class="excerpt">${E(t.text.replace(/^(Aufgabe[^\n]*\n|Hier:[^\n]*\n)+/i,''))}</p><div class="tags">${t.tags.slice(0,3).map(x=>`<span class="tag">${E(x)}</span>`).join('')}${variants>1?`<span class="tag">${variants} Varianten</span>`:''}</div><div class="card-meta"><span>◷ ${num(t.minutes,' Min.')}</span><span>◈ ${num(t.points,' Pkt.')}</span><span>${t.sourceIds.length} Quelle${t.sourceIds.length!==1?'n':''}</span></div><div class="card-footer">${btn('detail','Ansehen ↗','ghost small',t.id)}${btn('add','+ Zur Prüfung','small',t.id)}</div></article>`;}
function drawerView(){const e=current(),tot=e?C.totals(e):null;return `<aside class="drawer"><div class="drawer-title"><div><p class="eyebrow">Dein Prüfungsentwurf</p><h2>Prüfung zusammenstellen</h2></div><span class="pill-count">${e?.items.length||0}</span></div>${scopedExams().length?`<label for="selected-exam">Aktive Prüfung</label><select id="selected-exam"><option value="">Prüfung auswählen …</option>${scopedExams().map(x=>`<option value="${E(x.id)}" ${x.id===examId?'selected':''}>${E(x.title)}</option>`).join('')}</select>`:'<p class="sub">Aufgaben aus der Bank hinzufügen und zu einer neuen Prüfung verbinden.</p>'}${e?`<p class="sub" style="margin-top:10px">${E(e.specialty)} · ${E(e.date||'Termin offen')}${e.status==='used'?' · Einsatz dokumentiert':''}</p>${coverageView(e)}<div id="dropzone" class="dropzone">Aufgaben hierher ziehen<br><span class="tiny">oder „Zur Prüfung“ verwenden</span></div><div>${e.items.map((i,n)=>`<div class="exam-item" draggable="true" data-drag-item="${E(i.id)}" data-drop-item="${E(i.id)}"><div class="row"><span class="num">${n+1}</span><div><strong>${E(i.task.title)}</strong><span class="tiny">${num(i.task.points,' Pkt.')} · ${num(i.task.minutes,' Min.')}</span></div></div><div class="item-actions">${btn('item-up','↑','ghost',i.id)}${btn('item-down','↓','ghost',i.id)}${btn('item-edit','Bearbeiten','ghost',i.id)}${btn('item-remove','✕','ghost danger',i.id)}</div></div>`).join('')}</div><div class="totals"><div><strong>${tot.points}${tot.unknownPoints?' + ?':''}</strong><span>Punkte gesamt</span></div><div><strong>${tot.minutes}${tot.unknownMinutes?' + ?':''}</strong><span>Minuten gesamt</span></div></div>${!C.readiness(e).ready?`<div class="callout warning"><strong>Entwurf · Freigaben offen</strong>${C.readiness(e).issues.length} Hinweise vor dem Einsatz prüfen.</div>`:'<div class="callout"><strong>Fachlich freigegeben</strong>Aufgaben und Lösungen sind vollständig bestätigt.</div>'}${btn('preview-candidate','Teilnehmerfassung ansehen','wide')}${btn('preview-solution','Lösung & Bewertung ansehen','wide')}${btn('export-exam','↓ Prüfung + Lösung exportieren','primary wide')}${btn('edit-exam','Prüfungsdaten bearbeiten','ghost wide')}`:`<div id="dropzone" class="dropzone"><div style="font-size:32px;margin-bottom:10px">▤</div>Hier wächst die nächste Prüfung.<br>Die erste Aufgabe legt einen Entwurf an.</div>${btn('new-exam','+ Prüfung anlegen','primary wide')}`}<div class="hr-label">Gut zu wissen</div><p class="tiny">Aufgaben und Lösungen werden als feste Kopien in der Prüfung gespeichert. Die Reihenfolge lässt sich per Ziehen oder Pfeiltasten ändern.</p></aside>`;}
function familiesView(){const q=query.toLocaleLowerCase('de'),families=db.families.filter(f=>activeTasks().some(t=>t.familyId===f.id)&&[f.title,...activeTasks().filter(t=>t.familyId===f.id).map(t=>t.text)].join(' ').toLocaleLowerCase('de').includes(q));return `<p class="eyebrow">Wiederholungen erkennen</p><h1>Familien & Varianten</h1><p class="intro">Eine Familie beschreibt dieselbe grundlegende Arbeitsaufgabe. Varianten unterscheiden sich etwa in Kultur, Menge, Material oder Arbeitsschritten. Die Zuordnungen aus dem Altbestand sind Vorschläge.</p><div class="toolbar"><div class="search"><input id="search" aria-label="Familien suchen" type="search" value="${E(query)}" placeholder="Aufgabenfamilie suchen …"></div></div><div class="panel">${families.map(f=>{const ts=activeTasks().filter(t=>t.familyId===f.id),ys=[...new Set(ts.flatMap(years))].sort();return `<div class="family-row"><div><h3>${E(f.title)}</h3><span class="tiny">${ts.length} Variante${ts.length!==1?'n':''} · Quelljahre ${ys.join(', ')||'offen'} · ${f.reviewStatus==='approved'?'Zuordnung bestätigt':'Zuordnung prüfen'}</span></div>${btn('family','Vergleichen →','small',f.id)}</div>`;}).join('')}</div>`;}
function examsView(){return `<p class="eyebrow">Von der Auswahl zum Prüfungsbogen</p><h1>Meine Prüfungen</h1><p class="intro">Jeder Entwurf enthält eine Teilnehmerfassung und eine automatisch erzeugte Prüferfassung mit genau denselben Aufgaben und zugehörigen Lösungen.</p>${scopedExams().length?scopedExams().map(e=>{const t=C.totals(e),r=C.readiness(e);return `<div class="panel"><div class="row between"><h3>${E(e.title)}</h3><span class="badge ${r.ready?'':'amber'}">${e.status==='used'?'Einsatz dokumentiert':r.ready?'Freigaben vollständig':'Entwurf'}</span></div><p class="muted">${E(e.specialty)} · ${E(e.examType)} · ${E(e.date||'Termin offen')}</p><p class="tiny">${e.items.length} Aufgaben · ${t.points}${t.unknownPoints?' + offene':''} Punkte · ${t.minutes}${t.unknownMinutes?' + offene':''} Minuten</p><div class="toolbar">${btn('select-exam','Öffnen','primary',e.id)}${btn('duplicate-exam','Duplizieren','',e.id)}${btn('use-exam','Tatsächlichen Einsatz dokumentieren','',e.id)}</div></div>`;}).join(''):`<div class="panel empty"><div class="symbol">▤</div><h3>Platz für deine nächste Prüfung</h3><p>Wähle zuerst Fachrichtung, Prüfungsart und Termin.</p>${btn('new-exam','+ Erste Prüfung anlegen','primary')}</div>`}`;}
function importView(){const q=query.toLocaleLowerCase('de'),ss=db.sources.filter(s=>[s.name,s.specialty,s.role,s.flags?.join(' ')].join(' ').toLocaleLowerCase('de').includes(q));return `<p class="eyebrow">Originale bleiben nachvollziehbar</p><h1>Import & Quellen</h1><div class="grid2"><div class="panel"><h3>Weitere Word-Aufgaben</h3><p class="intro">DOCX-Dateien lokal einlesen. Text und eingebettete Bilder werden übernommen; Aufgabenaufteilung und Zuordnung anschließend prüfen.</p>${btn('docx','↑ DOCX-Dateien wählen','primary')}<p class="tiny" style="margin-top:12px">Alte .doc-Dateien vorher in Word als .docx speichern. Vorhandene Originale aus dem Altbestand bleiben erhalten.</p></div><div class="panel"><h3>Bestand ergänzen oder öffnen</h3><p class="intro">Zusätzliche Datenpakete der Koordination zusammenführen. Abweichende Datensätze werden als eigene Kopien erhalten.</p>${btn('merge-project','↑ JSON zusammenführen')}${btn('open-project','Separates Projekt öffnen','ghost')}<p class="tiny" style="margin-top:12px">Vor einem Projektwechsel zuerst den aktuellen Stand sichern.</p></div></div><div class="callout warning"><strong>Einlesen ist noch keine fachliche Freigabe.</strong>Word-Layout, Tabellen, Zeichnungsbezüge, Aufgabenabgrenzung und Bewertung bitte anhand der erhaltenen Originale kontrollieren. Ein Dateijahr wird nicht als bestätigter Prüfungstermin übernommen.</div><div class="toolbar"><div class="search"><input id="search" aria-label="Quellen suchen" type="search" value="${E(query)}" placeholder="Original, Fachrichtung oder Hinweis suchen …"></div></div><div class="panel"><div class="row between"><h3>Quellenarchiv</h3><span class="tiny">${ss.length} Dokumente</span></div>${ss.slice(0,limit).map(s=>`<div class="source-row"><div><strong>${E(s.name)}</strong><div class="path">${E(s.specialty)} · ${E(s.examType)} · ${E(s.role)} · ${s.year||'Jahr offen'}</div>${s.flags?.length?`<span class="badge amber">${s.flags.length} Quellenhinweis${s.flags.length>1?'e':''}</span>`:''}</div>${btn('source','Öffnen','small',s.id)}</div>`).join('')}${ss.length>limit?btn('more','Weitere Quellen anzeigen','wide ghost'):''}</div>`;}
function aboutView(){return `<p class="eyebrow">Prüfungswerkstatt</p><h1>Vom Muster zur praktischen Prüfung.</h1><div class="panel"><ol><li>Prüfungsart und Fachrichtung wählen.</li><li>Kategorien und Anzahlen im Prüfungsmuster fachlich bestätigen.</li><li>Innerhalb der Kategorien Familien und Varianten vergleichen oder Rotationsvorschläge übernehmen.</li><li>Aufgaben, Lösungen, Punkte und Anlagen prüfen. Kombinationsaufgaben decken mehrere Kategorien ab.</li><li>Die zuständige Stelle sichert den Entwurf und erzeugt Teilnehmer- und Prüferfassung.</li><li>Erst nach tatsächlicher Durchführung den Einsatz dokumentieren.</li></ol></div><div class="callout warning"><strong>Koordinationstest, kein abgesicherter Prüferbetrieb</strong>Die aktuelle Website speichert nicht zentral. Keine Offline-Satelliten. Temporäre Sitzungen und Exportrechte benötigen eine zusätzliche serverseitige Zugangskontrolle. Unter „Zugänge & Rechte“ ist der vorgesehene Ablauf beschrieben.</div><div class="panel"><h3>Historie richtig lesen</h3><p>Ein Quelldokument belegt ein Dokumentjahr, keinen bestätigten Einsatz. Bei der Rotation zählt die gesamte Aufgabenfamilie einschließlich älterer Revisionen. Die aktuelle Variante allein setzt die Historie nicht zurück.</p><p>Historische Kategorieüberschriften liefern Vorschläge. Ein unvollständiges Archiv beweist keine vollständige jährliche Prüfungszusammensetzung. Die Koordination bestätigt deshalb das Muster ausdrücklich.</p></div>`;}
function wireInputs(){const search=$('#search');if(search)search.addEventListener('input',()=>{query=search.value;limit=24;const at=search.selectionStart;render();$('#search')?.focus();try{$('#search')?.setSelectionRange(at,at);}catch{}});for(const [sel,set] of [['#filter-fr',v=>fr=v],['#filter-type',v=>type=v],['#filter-category',v=>category=v],['#filter-kind',v=>kind=v],['#filter-year',v=>year=v],['#filter-quality',v=>quality=v]])$(sel)?.addEventListener('change',e=>{set(e.target.value);limit=24;render();});$('#selected-exam')?.addEventListener('change',e=>{examId=e.target.value;render();});}
function detail(id){const t=db.tasks.find(t=>t.id===id);if(!t)return;const f=family(t.familyId),ys=years(t),uses=db.uses.filter(u=>u.taskIds.includes(t.id));openModal(t.title,`<div class="row"><span class="badge">${E(t.examType)} · ${E(t.specialty)}</span><span class="badge amber">${E(solutionLabel(t))}</span></div><div class="grid3" style="margin-top:20px"><div><label>Punkte</label>${num(t.points)}</div><div><label>Bearbeitungszeit</label>${num(t.minutes,' Minuten')}</div><div><label>Quelljahre</label>${ys.join(', ')||'Unbekannt'}</div></div><h3 class="section-title">Aufgabenstellung</h3><div class="pretext">${E(t.text)}</div>${P.graphics(t,db,true)}${categoryFields(t)}<h3 class="section-title">Lösung / Erwartungshorizont</h3><div class="pretext">${E(t.solution||'Keine Musterlösung in der Aufgabenbank hinterlegt.')}</div>${t.criteria.length?`<h3 class="section-title">Bewertung / Teilpunkte</h3><table class="criteria"><tr><th>Kriterium</th><th>Punkte</th><th>Erwartete Leistung</th></tr>${t.criteria.map(c=>`<tr><td>${E(c.text)}</td><td>${num(c.points)}</td><td>${E(c.answer||'offen')}</td></tr>`).join('')}</table>`:''}<h3 class="section-title">Familie und Historie</h3><p>${E(f?.title)} ${btn('family','Varianten vergleichen','small',t.familyId)}</p><div class="timeline"><div><strong>Zuletzt im Quellenbestand:</strong> ${lastYear(t)} · aus Dateinamen, nicht als Einsatz bestätigt</div><div><strong>Bestätigte Einsätze dieser Aufgabe / abgeleiteter Fassungen:</strong> ${uses.map(u=>E(u.date)).join(', ')||'Noch keine dokumentiert'}</div></div>${t.flags.length?`<div class="callout warning"><strong>Vor Verwendung prüfen</strong>${t.flags.map(E).join('<br>')}</div>`:''}${t.previousId&&db.tasks.some(v=>v.id===t.previousId)?btn('detail','← Frühere Revision ansehen','small',t.previousId):''}${t.supersededBy?btn('detail','Aktuelle Revision ansehen →','small',t.supersededBy):''}<h3 class="section-title">Originale & Anlagen</h3>${t.sourceIds.map(sid=>{const s=source(sid);return `<div class="source-row"><div><strong>${E(s.name)}</strong><div class="tiny">${s.year||'Jahr offen'} · ${E(s.yearEvidence==='filename'?'Zuordnung aus Dateiname':'Zuordnung offen')}</div></div>${btn('source','Quelle ansehen','small',sid)}</div>`;}).join('')}`,`${btn('edit-task','Aufgabe als neue Revision bearbeiten','',t.id)}${btn('add','+ Zur Prüfung','primary',t.id)}`);}
function showFamily(id){const f=family(id),ts=db.tasks.filter(t=>t.familyId===id&&t.examType===type&&t.specialty===fr);const controls=ts.map(t=>`<option value="${E(t.id)}">${E(t.title)}${t.supersededBy?' [frühere Revision]':''} · ${years(t).join('/')||'ohne Jahr'} · ${E(t.specialty)}</option>`).join('');openModal('Aufgabenfamilie: '+f.title,`<p class="intro">Zuordnung: ${f.reviewStatus==='approved'?'bestätigt':'Vorschlag, fachlich prüfen'}. Gelb markierte Zeilen kommen nur in der jeweiligen Fassung vor. Identischer Text allein beweist keine identischen Pläne oder Anforderungen.</p>${ts.length>1?`<div class="grid2"><div><label>Linke Variante</label><select id="compare-left">${controls}</select></div><div><label>Rechte Variante</label><select id="compare-right">${controls}</select></div></div><div id="comparison" style="margin-top:18px"></div>`:ts.map(t=>`<div class="panel"><h3>${E(t.title)}</h3><p class="tiny">Quelljahre: ${years(t).join(', ')||'offen'}</p><div class="pretext">${E(t.text)}</div></div>`).join('')}`,btn('confirm-family','Familienzuordnung bestätigen','primary',id));if(ts.length>1){$('#compare-right').selectedIndex=1;const draw=()=>{const a=ts.find(t=>t.id===$('#compare-left').value),b=ts.find(t=>t.id===$('#compare-right').value);$('#comparison').innerHTML=`<div class="compare">${[[a,b],[b,a]].map(([t,other])=>`<div><h3>${E(t.title)}</h3><p class="tiny">${E(t.specialty)} · ${years(t).join(', ')} · ${num(t.points,' Pkt.')} · ${num(t.minutes,' Min.')}</p><div class="pretext">${t.text.split('\n').map(l=>other.text.split('\n').includes(l)?E(l):`<mark>${E(l)}</mark>`).join('\n')}</div><p class="tiny">${t.assetLinks.length} Anlagen · ${solutionLabel(t)}</p>${btn('detail','Aufgabe mit Quellen ansehen','small',t.id)}</div>`).join('')}</div>`;};$('#compare-left').onchange=draw;$('#compare-right').onchange=draw;draw();}}
function sourceModal(id){const s=source(id);openModal(s.name,`<p class="tiny">${E(s.path||s.name)}</p><div class="row"><span class="badge">${E(s.role)}</span><span class="badge">${E(s.specialty)}</span></div>${s.flags?.length?`<div class="callout warning">${s.flags.map(E).join('<br>')}</div>`:''}<p class="tiny" style="margin-top:15px">Quelljahr: ${s.year||'offen'} · ${s.yearEvidence==='filename'?'aus Dateiname, kein bestätigter Einsatz':'Zuordnung offen'}</p><h3 class="section-title">Ausgelesener Text</h3><div class="pretext">${E(s.text)}</div><h3 class="section-title">Eingebettete Anlagen</h3>${s.attachmentIds.map(id=>{const a=asset(id);return `<div class="asset-line">${/^image\/(png|jpeg|webp|gif)$/.test(a.mime)?`<img class="graphic" src="data:${a.mime};base64,${a.data}" alt="${E(a.name)}">`:''}<p class="tiny">${E(a.name)}</p>${btn('download-asset','Anlage herunterladen','small',a.id)}</div>`;}).join('')||'<p class="tiny">Keine eingebetteten Bilder erkannt.</p>'}`,btn('download-source','↓ Originaldokument herunterladen','primary',s.id));}
function freshTask(){return {id:C.id('task'),familyId:'',title:'',text:'',examType:type||'ZP',specialty:fr||FR[0],category:'Praktische Arbeitsaufgabe',tags:[],sourceIds:[],assetLinks:[],criteria:[],points:null,minutes:null,solution:'',solutionStatus:'missing',reviewStatus:'review',flags:[],kind:'practical',qualification:'Nicht gesondert angegeben',createdAt:C.now()};}
function editTask(id,mode='bank'){let t=mode==='item'?current()?.items.find(i=>i.id===id)?.task:db.tasks.find(t=>t.id===id);modalTask=C.clone(t||freshTask());if(t){modalTask.reviewStatus='review';if(modalTask.solutionStatus==='approved')modalTask.solutionStatus='draft';}modalMode={mode,id};pendingAssets=[];taskForm();}
function taskForm(){const t=modalTask;openModal(modalMode.mode==='item'?'Aufgabe in dieser Prüfung bearbeiten':modalMode.id?'Neue Revision erstellen':'Eigene Aufgabe anlegen',`<div class="callout">${modalMode.mode==='item'?'Änderungen gelten nur für diese Prüfung. Die Fragenbank bleibt unverändert.':'Bestehende Aufgaben bleiben als frühere Revision erhalten. Neue Prüfungen können die überarbeitete Fassung verwenden.'}</div><div class="field"><label for="task-title">Titel *</label><input id="task-title" value="${E(t.title)}"></div><div class="grid3"><div class="field"><label>Fachrichtung</label><select id="task-fr">${options(FR,t.specialty)}</select></div><div class="field"><label>Prüfungsart</label><select id="task-type">${typeOptions(t.examType)}</select></div><div class="field"><label>Bestandsteil</label><select id="task-kind">${[['practical','Praktisch'],['oral','Mündlich'],['other','Weitere']].map(([v,l])=>`<option value="${v}" ${t.kind===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="field"><label>Aufgabenfamilie</label><select id="task-family"><option value="">Neue Familie aus Aufgabentitel</option>${db.families.filter(f=>db.tasks.some(v=>v.familyId===f.id&&v.examType===t.examType&&v.specialty===t.specialty)||f.id===t.familyId).map(f=>`<option value="${E(f.id)}" ${t.familyId===f.id?'selected':''}>${E(f.title)}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>Kategorie / Arbeitsbereich</label><input id="task-category" value="${E(t.category)}"></div><div class="field"><label>Tags (durch Komma getrennt)</label><input id="task-tags" value="${E(t.tags.join(', '))}"></div></div><div class="field"><label>Ausbildungsgang / Kennziffer</label><input id="task-qualification" value="${E(t.qualification||'')}"></div><div class="field"><label for="task-text">Aufgabenstellung *</label><textarea id="task-text" rows="10">${E(t.text)}</textarea><p class="tiny">Teilaufgaben und Reihenfolge vollständig erhalten. Neue eigenständige Aufgaben können separat angelegt werden.</p></div><div class="grid2"><div class="field"><label>Gesamtpunkte (leer = unbekannt)</label><input id="task-points" type="number" min="0" step="0.5" value="${t.points??''}"></div><div class="field"><label>Bearbeitungszeit in Minuten (leer = unbekannt)</label><input id="task-minutes" type="number" min="0" value="${t.minutes??''}"></div></div><h3 class="section-title">Grafiken, Pläne & Anlagen</h3><div id="task-assets">${t.assetLinks.map((l,i)=>{const a=asset(l.assetId)||pendingAssets.find(a=>a.id===l.assetId);return `<div class="asset-line" data-asset-index="${i}"><div class="row between"><strong class="tiny">${E(a?.name||'Anlage')}</strong>${btn('remove-link','Entfernen','small danger',String(i))}</div>${a&&/^image\/(png|jpeg|webp|gif)$/.test(a.mime)?`<img src="data:${a.mime};base64,${a.data}" alt="${E(a.name)}">`:''}<label>Verwendung</label><select data-asset-audience="${i}">${[['source','Nur Original / Quellenarchiv'],['candidate','Teilnehmer- und Prüferfassung'],['examiner','Nur Lösung / Prüferfassung']].map(([v,x])=>`<option value="${v}" ${l.audience===v?'selected':''}>${x}</option>`).join('')}</select><label style="margin-top:8px">Bildunterschrift</label><input data-asset-caption="${i}" value="${E(l.caption||'')}"></div>`;}).join('')}</div>${btn('add-asset','+ Grafik / Plan hinzufügen')}<p class="tiny">PNG/JPG/WebP werden direkt in die Prüfung gedruckt. PDF-Anlagen werden separat mitgeliefert.</p>${categoryFields(t)}<h3 class="section-title">Lösung / Erwartungshorizont</h3><div class="field"><label for="task-solution">Musterlösung bzw. erwartete praktische Durchführung</label><textarea id="task-solution" rows="7" placeholder="Fachliche Lösung, zulässige Alternativen und wesentliche Beobachtungskriterien …">${E(t.solution)}</textarea></div><div class="grid2"><div class="field"><label>Lösungsstatus</label><select id="task-solution-status">${[['missing','Fehlt'],['draft','Entwurf'],['approved','Fachlich freigegeben']].map(([v,l])=>`<option value="${v}" ${t.solutionStatus===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Fachlicher Prüfstatus der Aufgabe</label><select id="task-review"><option value="review" ${t.reviewStatus!=='approved'?'selected':''}>Noch prüfen</option><option value="approved" ${t.reviewStatus==='approved'?'selected':''}>Fachlich geprüft</option></select></div></div><div class="field"><label>Freigabe / geprüft durch (Name oder Kürzel)</label><input id="task-reviewer" value="${E(t.reviewedBy||'')}"></div><h3 class="section-title">Teilpunkte und Bewertung</h3><table class="criteria"><thead><tr><th>Kriterium / Teilaufgabe</th><th>Erwartete Leistung</th><th>Punkte</th><th></th></tr></thead><tbody>${t.criteria.map((c,i)=>`<tr><td><textarea data-criterion-text="${i}">${E(c.text)}</textarea></td><td><textarea data-criterion-answer="${i}">${E(c.answer)}</textarea></td><td><input data-criterion-points="${i}" type="number" min="0" step="0.5" value="${c.points??''}"></td><td>${btn('remove-criterion','✕','ghost danger',String(i))}</td></tr>`).join('')}</tbody></table><div class="toolbar">${btn('add-criterion','+ Bewertungskriterium')}${btn('sum-points','Teilpunkte als Gesamtpunkte übernehmen','ghost')}</div><div class="field"><label>Offene Hinweise (eine Zeile je Hinweis; erst nach Klärung entfernen)</label><textarea id="task-flags" rows="3">${E(t.flags.join('\n'))}</textarea></div>`,`${btn('close','Abbrechen')}${btn('save-task','Änderungen speichern','primary')}`);}
function readTaskForm(){const t=modalTask;const n=sel=>$(sel).value===''?null:Number($(sel).value);Object.assign(t,{title:$('#task-title').value.trim(),text:$('#task-text').value.trim(),specialty:$('#task-fr').value,examType:$('#task-type').value,kind:$('#task-kind').value,familyId:$('#task-family').value,category:$('#task-category').value.trim(),tags:$('#task-tags').value.split(',').map(x=>x.trim()).filter(Boolean),qualification:$('#task-qualification').value.trim(),points:n('#task-points'),minutes:n('#task-minutes'),solution:$('#task-solution').value.trim(),solutionStatus:$('#task-solution-status').value,reviewStatus:$('#task-review').value,reviewedBy:$('#task-reviewer').value.trim(),flags:$('#task-flags').value.split('\n').map(x=>x.trim()).filter(Boolean)});const selected=$$('[data-planning-category]:checked').map(x=>x.value);if(selected.length){t.planningCategories=selected;t.planningCategoryEvidence='Manuell in der Prüfungswerkstatt zugeordnet';}else{delete t.planningCategories;delete t.planningCategoryEvidence;}t.criteria=t.criteria.map((c,i)=>({...c,text:$(`[data-criterion-text="${i}"]`).value,answer:$(`[data-criterion-answer="${i}"]`).value,points:n(`[data-criterion-points="${i}"]`)}));t.assetLinks=t.assetLinks.map((l,i)=>({...l,audience:$(`[data-asset-audience="${i}"]`).value,caption:$(`[data-asset-caption="${i}"]`).value}));return t;}
function saveTask(){const t=readTaskForm();if(isGroup){if(modalMode.mode!=='item')throw Error('Bitte nur die Aufgabe im Prüfungsentwurf bearbeiten.');t.reviewStatus='review';t.solutionStatus=t.solution?'draft':'missing';t.reviewedBy='';delete t.reviewedAt;}const assigned=$$('[data-planning-category]:checked').map(x=>x.value);if(assigned.length){t.planningCategories=assigned;t.planningCategoryEvidence='Manuell in der Prüfungswerkstatt zugeordnet';}if(!t.title||!t.text)throw Error('Bitte Titel und Aufgabenstellung ausfüllen.');if((t.reviewStatus==='approved'||t.solutionStatus==='approved')&&!t.reviewedBy)throw Error('Für die Freigabe bitte Name oder Kürzel angeben.');if(t.solutionStatus==='approved'&&!t.solution)throw Error('Eine leere Lösung kann nicht freigegeben werden.');if(t.solution&&t.solutionStatus==='missing')t.solutionStatus='draft';C.checkTask(t);if(modalMode.mode==='item'&&(t.specialty!==current().specialty||t.examType!==current().examType))throw Error('Fachrichtung und Prüfungsart müssen zur Prüfung passen.');if(!t.familyId){t.familyId=C.id('family');db.families.push({id:t.familyId,title:t.title,reviewStatus:'review'});}for(const a of pendingAssets)if(!db.assets.some(x=>x.id===a.id))db.assets.push(a);if(!isGroup)t.reviewedAt=C.now();if(modalMode.mode==='item'){const e=current(),i=e.items.find(i=>i.id===modalMode.id);i.task=C.clone(t);e.updatedAt=C.now();e.status='draft';}else if(modalMode.id){const next=C.revise(db,modalMode.id,t); // Explicit review in this dialog applies to the edited content.
 if(t.solutionStatus==='approved')next.solutionStatus='approved';
}else db.tasks.push(C.clone(t));changed();closeModal();render();toast('Aufgabe gespeichert. Bestehende Prüfungskopien bleiben erhalten.');}
function examForm(e=null){if(!type||!fr){route='scope';render();toast('Zuerst Prüfungsart und Fachrichtung wählen.');return;}openModal(e?'Prüfungsdaten bearbeiten':'Neue praktische Prüfung',`<div class="field"><label>Titel *</label><input id="exam-title" value="${E(e?.title||('Praktische '+(type==='AP'?'Abschlussprüfung':'Zwischenprüfung')+' '+targetYear()))}"></div><div class="grid2"><div class="field"><label>Fachrichtung</label><select id="exam-fr">${options(FR,e?.specialty||fr||FR[0])}</select></div><div class="field"><label>Prüfungsart</label><select id="exam-type">${typeOptions(e?.examType||type||'ZP')}</select></div></div><div class="grid2"><div class="field"><label for="exam-year">Prüfungsjahr</label><input id="exam-year" type="number" min="1900" max="2200" step="1" value="${e?.examYear||targetYear()}"></div><div class="field"><label for="exam-workshop">Vorbereitungstermin</label><select id="exam-workshop"><option value="">Keinem Termin zugeordnet</option>${db.workshops.map(w=>`<option value="${E(w.id)}" ${w.id===(e?e.workshopId:workshopId)?'selected':''}>${E(w.title)} · ${w.examYear}</option>`).join('')}</select></div></div><div class="field"><label>Geplanter Prüfungstermin</label><input id="exam-date" type="date" value="${E(e?.date||'')}"></div><div class="field"><label>Hinweise für Teilnehmende</label><textarea id="exam-notes" rows="3">${E(e?.notes||'')}</textarea></div>`,`${btn('close','Abbrechen')}${btn(e?'save-exam':'create-exam',e?'Speichern':'Prüfung anlegen','primary',e?.id||'')}`);}
function saveExam(id){const fields={title:$('#exam-title').value.trim(),specialty:$('#exam-fr').value,examType:$('#exam-type').value,date:$('#exam-date').value,notes:$('#exam-notes').value,examYear:Number($('#exam-year').value),...($('#exam-workshop').value?{workshopId:$('#exam-workshop').value}:{})};C.checkExamWorkshop(db,fields);if(!fields.title)throw Error('Bitte einen Prüfungstitel eingeben.');L.checkPattern(L.pattern(db,fields.examType,fields.specialty));if(fields.date&&!C.validDate(fields.date))throw Error('Bitte gültiges Datum eingeben.');let e=id?db.exams.find(e=>e.id===id):C.newExam({...fields,pattern:L.pattern(db,fields.examType,fields.specialty)});if(e.items.some(i=>i.task.specialty!==fields.specialty||i.task.examType!==fields.examType))throw Error('Fachrichtung und Prüfungsart passen nicht zu den bereits ausgewählten Aufgaben.');if(!e.pattern||e.pattern.examType!==fields.examType||e.pattern.specialty!==fields.specialty)e.pattern=C.clone(L.pattern(db,fields.examType,fields.specialty));delete e.workshopId;Object.assign(e,fields,{updatedAt:C.now()});if(!id)db.exams.push(e);examId=e.id;workshopId=e.workshopId||null;fr=e.specialty;type=e.examType;changed();closeModal();route='bank';render();toast('Prüfung gespeichert. Jetzt Aufgaben hinzufügen.');}
function addToExam(id){const t=db.tasks.find(t=>t.id===id);if(!t)return;if(t.examType!==type||t.specialty!==fr)throw Error('Aufgabe passt nicht zum gewählten Prüfungsbereich.');let e=current();if(!e){L.checkPattern(L.pattern(db,t.examType,t.specialty));e=C.newExam({title:`Praktische ${t.examType==='AP'?'Abschlussprüfung':'Zwischenprüfung'} ${targetYear()}`,specialty:t.specialty,examType:t.examType,examYear:targetYear(),...(meeting()?{workshopId:meeting().id}:{}),pattern:L.pattern(db,t.examType,t.specialty)});C.checkExamWorkshop(db,e);db.exams.push(e);examId=e.id;}if(e.status==='used')throw Error('Diese Prüfung wurde bereits eingesetzt. Bitte zuerst duplizieren.');if(e.specialty!==t.specialty||e.examType!==t.examType)throw Error('Die Aufgabe gehört zu einer anderen Fachrichtung oder Prüfungsart. Passende Prüfung anlegen oder auswählen.');if(e.items.some(i=>i.task.familyId===t.familyId))throw Error('Diese Aufgabenfamilie ist bereits enthalten. Für eine andere Variante bitte zuerst die bisherige Aufgabe entfernen.');C.addItem(e,t);changed();render();toast('Aufgabe mit Lösung und Anlagen zur Prüfung hinzugefügt.');}
function editableExam(){const e=current();if(!e)throw Error('Bitte eine Prüfung auswählen.');if(e.status==='used')throw Error('Bereits eingesetzte Prüfung bitte zuerst duplizieren.');return e;}
function preview(examiner){const e=current();if(!e?.items.length)throw Error('Bitte zuerst Aufgaben auswählen.');openModal(examiner?'Lösungsklausur / Prüferfassung':'Teilnehmerfassung',`<iframe id="print-preview" class="preview" sandbox="allow-scripts allow-modals" title="${examiner?'Lösungsklausur':'Teilnehmerfassung'}"></iframe><p class="tiny">Zum PDF-Druck die exportierte HTML-Datei im Browser öffnen. Bei Bildern und Plänen Druckmaßstab kontrollieren.</p>`,btn('export-exam','↓ Beide Fassungen exportieren','primary'));$('#print-preview').srcdoc=isGroup?P.document(e,db,examiner).replace(/<div class="toolbar">[\s\S]*?<\/div>/,'').replace('</head>','<style>@media print{body{display:none!important}}</style></head>'):P.document(e,db,examiner);}
function offerDownload(blob,name,message){const url=URL.createObjectURL(blob);openModal('Datei ist bereit',`<p>${E(message)}</p><p class="intro">Die Datei enthält vertrauliche Prüfungsunterlagen. Wählen Sie einen geeigneten Speicherort.</p><a class="download-link" id="ready-download" href="${url}" download="${E(name)}">↓ ZIP herunterladen</a>`,btn('close','Schließen'));$('#ready-download').addEventListener('click',()=>{setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Download gestartet.');},{once:true});}
async function exportExam(){if(online){await flush();await online.request('/api/export');}const e=current();if(!e?.items.length)throw Error('Bitte zuerst Aufgaben auswählen.');const z=new JSZip();z.file('01_Teilnehmerfassung.html',P.document(e,db,false));z.file('02_Loesung_und_Bewertung.html',P.document(e,db,true));for(const file of P.attachments(e,db,true)){const a=asset(file.assetId);z.file(file.path,a.data,{base64:true});}z.file('LESEN.txt','Vertrauliche Prüfungsunterlagen.\n01_Teilnehmerfassung.html enthält keine Musterlösungen.\n02_Loesung_und_Bewertung.html ist ausschließlich für Prüfer.\nHTML-Datei im Browser öffnen, Drucken wählen und ggf. als PDF speichern.\nSeparate Anlagen ergänzen; Maßstab und Seitenumbrüche prüfen.\nEntwurfskennzeichnung bedeutet: Freigaben oder Informationen fehlen.\nDas ZIP mit Prüferfassung nicht an Prüflinge weitergeben.\n');offerDownload(await z.generateAsync({type:'blob',compression:'DEFLATE'}),safeName(e.title)+'.zip','Prüfung und Lösungsklausur wurden erstellt. Der Entwurfsstatus steht in beiden Fassungen.');}
const actions={
 'save-conflict-copy':async()=>{clearTimeout(saveTimer);$('#app').inert=true;$('#dialog').inert=true;try{if(saving){try{await saving;}catch(e){if(e.status!==409)throw e;}}clearTimeout(saveTimer);if(!dirty)return;db=await online.saveCopies(C.clone(db));dirty=false;saveError=null;storageText='Konfliktkopien zentral gespeichert';examId=null;render();toast('Ihre Änderungen sind als separate Konfliktkopien gespeichert.');}finally{$('#app').inert=false;$('#dialog').inert=false;}},'save-online':flush,'reload-online':reloadCentral,'logout':async()=>{await flush();await online.logout();},'open-session':openSession,'close-session':closeSession,'refresh-access':async()=>{await online.access();render();},'approve-device':id=>decideDevice(id,true),'revoke-device':id=>decideDevice(id,false),'copy-invitation':copyInvitation,

 'new-workshop':()=>workshopForm(), 'edit-workshop':()=>workshopForm(true),'save-workshop':saveWorkshop,'invitation':invitation,
 'open-group':id=>{fr=id;type='';category='';examId=null;route='group';render();},
 'track-pattern':id=>{type=id;examId=null;category='';route='patterns';render();},
 'track-new':id=>{type=id;examId=null;category='';examForm();},

 'choose-type':id=>{workshopId=null;type=id;fr='';examId=null;category='';route='scope';render();},
 'choose-specialty':id=>{fr=id;examId=null;category='';route='patterns';render();},
 'choose-category':id=>{category=id;query='';route='bank';render();},
 'all-categories':()=>{category='';route='bank';render();},
 'save-pattern':savePattern,
 'apply-pattern':()=>{const e=editableExam();const p=L.pattern(db,e.examType,e.specialty);L.checkPattern(p);e.pattern=C.clone(p);changed();render();},
 'suggest':suggestTasks,'accept-suggestions':acceptSuggestions,

 'close':closeModal,'backup':backup,'new-exam':()=>examForm(),'new-task':()=>editTask(null),'edit-task':id=>editTask(id),'detail':detail,'family':showFamily,'source':sourceModal,
 'add':addToExam,'more':()=>{limit+=30;render();},'clear-filters':()=>{query=category=year=quality='';kind='practical';limit=24;render();},
 'confirm-family':id=>{family(id).reviewStatus='approved';changed();closeModal();render();toast('Familienzuordnung bestätigt.');},
 'create-exam':()=>saveExam(),'save-exam':saveExam,'edit-exam':()=>examForm(editableExam()),'select-exam':id=>{examId=id;workshopId=current().workshopId||null;category='';query='';route='bank';fr=current().specialty;type=current().examType;render();},
 'duplicate-exam':id=>{const e=C.clone(db.exams.find(e=>e.id===id));if(isGroup)e.basedOnExamId=e.id;e.id=C.id('exam');e.title+=' · Kopie';e.status='draft';e.createdAt=e.updatedAt=C.now();if(!isGroup)e.items.forEach(i=>i.id=C.id('item'));db.exams.push(e);examId=e.id;changed();render();},
 'use-exam':id=>{const e=db.exams.find(e=>e.id===id);openModal('Tatsächlichen Prüfungseinsatz dokumentieren',`<p>${E(e.title)}</p><p class="intro">Nur eintragen, wenn diese Prüfung tatsächlich durchgeführt wurde. Der geplante Termin allein zählt nicht als Einsatz.</p><div class="field"><label>Durchgeführt am</label><input id="use-date" type="date" max="${new Date().toISOString().slice(0,10)}" value="${E(e.date)}"></div><label class="check"><input type="checkbox" id="use-confirm">Ich bestätige den tatsächlichen Einsatz dieser Prüfungsfassung.</label>`,btn('save-use','Einsatz dokumentieren','primary',id));},
 'save-use':id=>{if(!$('#use-confirm').checked)throw Error('Bitte tatsächlichen Einsatz bestätigen.');C.recordUse(db,id,$('#use-date').value);changed();closeModal();render();},
 'item-up':id=>moveItem(id,-1),'item-down':id=>moveItem(id,1),'item-remove':id=>{const e=editableExam();e.items=e.items.filter(i=>i.id!==id);e.updatedAt=C.now();changed();render();},'item-edit':id=>{editableExam();editTask(id,'item');},
 'preview-candidate':()=>preview(false),'preview-solution':()=>preview(true),'export-exam':exportExam,
 'save-task':saveTask,'add-criterion':()=>{readTaskForm();modalTask.criteria.push({id:C.id('criterion'),text:'',answer:'',points:null});taskForm();},'remove-criterion':id=>{readTaskForm();modalTask.criteria.splice(Number(id),1);taskForm();},'sum-points':()=>{readTaskForm();if(modalTask.criteria.some(c=>c.points==null))throw Error('Bitte zuerst alle Teilpunkte ausfüllen.');modalTask.points=modalTask.criteria.reduce((s,c)=>s+c.points,0);taskForm();},'remove-link':id=>{readTaskForm();modalTask.assetLinks.splice(Number(id),1);taskForm();},'add-asset':()=>{readTaskForm();$('#asset-input').click();},
 'download-source':id=>{const s=source(id),a=asset(s.assetId);if(!a)throw Error('Für diese Quelle ist keine Originaldatei hinterlegt.');download(safeName(s.name),new Blob([Uint8Array.from(atob(a.data),c=>c.charCodeAt(0))],{type:'application/octet-stream'}));},
 'download-asset':id=>{const a=asset(id);if(!a)throw Error('Anlage fehlt.');const bytes=Uint8Array.from(atob(a.data),c=>c.charCodeAt(0));download(safeName(a.name),new Blob([bytes],{type:'application/octet-stream'}));},
 'merge-project':()=>{importMode='merge';$('#project-input').click();},'open-project':()=>{importMode='open';openModal('Anderes Projekt öffnen','<p>Der aktuelle Browser-Arbeitsstand wird durch die gewählte Projektdatei ersetzt. Eine vorher gesicherte Datei bleibt erhalten.</p><p class="intro">Zum Ergänzen des Bestands stattdessen „JSON zusammenführen“ verwenden.</p>',`${btn('backup','Aktuellen Stand sichern')}${btn('choose-open-project','Projektdatei auswählen','primary')}`);},'choose-open-project':()=>$('#project-input').click(),
 'docx':()=>openModal('Word-Aufgaben importieren',`<p class="intro">Die Dateien werden ausschließlich in diesem Browser verarbeitet. Neue Aufgaben landen im Prüfstatus „Noch prüfen“.</p><div class="grid2"><div class="field"><label>Fachrichtung der Dateien</label><select id="import-fr">${options(FR,fr||FR[0])}</select></div><div class="field"><label>Prüfungsart</label><select id="import-type">${typeOptions(type||'ZP')}</select></div></div>`,btn('choose-docx','DOCX-Dateien auswählen','primary')),
 'choose-docx':()=>$('#docx-input').click()
};
function moveItem(id,delta){const e=editableExam(),i=e.items.findIndex(x=>x.id===id),j=i+delta;if(i<0||j<0||j>=e.items.length)return;[e.items[i],e.items[j]]=[e.items[j],e.items[i]];e.updatedAt=C.now();changed();render();}
document.addEventListener('click',async ev=>{const nav=ev.target.closest('[data-route]');if(nav){if(isGroup&&!['group','patterns','bank','families','exams'].includes(nav.dataset.route))return;route=nav.dataset.route;if(['patterns','bank','families','exams'].includes(route)&&(!type||!fr))route='scope';query='';limit=24;render();return;}const button=ev.target.closest('[data-action]');if(!button)return;if(forbidden(button.dataset.action))return;const action=actions[button.dataset.action];if(!action)return;try{await action(button.dataset.id);}catch(error){toast(error.message||String(error));}});
document.addEventListener('dragstart',ev=>{const task=ev.target.closest('[data-drag-task]'),item=ev.target.closest('[data-drag-item]');if(item)ev.dataTransfer.setData('text/plain','item:'+item.dataset.dragItem);else if(task)ev.dataTransfer.setData('text/plain','task:'+task.dataset.dragTask);});
document.addEventListener('dragover',ev=>{const el=ev.target.closest('#dropzone,[data-drop-item]');if(el){ev.preventDefault();el.classList.add('dragover');}});
document.addEventListener('dragleave',ev=>ev.target.closest('#dropzone,[data-drop-item]')?.classList.remove('dragover'));
document.addEventListener('drop',ev=>{const el=ev.target.closest('#dropzone,[data-drop-item]');if(!el)return;ev.preventDefault();el.classList.remove('dragover');const payload=ev.dataTransfer.getData('text/plain');try{if(payload.startsWith('task:'))addToExam(payload.slice(5));else if(payload.startsWith('item:')){const e=editableExam(),id=payload.slice(5),i=e.items.findIndex(x=>x.id===id);if(i<0)return;const item=e.items.splice(i,1)[0],j=e.items.findIndex(x=>x.id===el.dataset.dropItem);e.items.splice(j<0?e.items.length:j,0,item);e.updatedAt=C.now();changed();render();}}catch(error){toast(error.message);}});
$('#project-input').addEventListener('change',async ev=>{const f=ev.target.files[0];ev.target.value='';if(!f)return;try{if(f.size>150*1024*1024)throw Error('Projektdatei ist größer als 150 MB.');const incoming=C.validate(JSON.parse(await f.text()));if(importMode==='open'){db=incoming;examId=null;type=fr=category='';workshopId=db.workshops[0]?.id||null;route='dashboard';dirty=false;}else{const r=C.merge(db,incoming);db=r.db;toast(`Import abgeschlossen. ${r.conflicts.length} abweichende Datensätze als separate Kopien erhalten.`);}changed();closeModal();render();}catch(error){toast('Import nicht übernommen: '+error.message);}});
$('#asset-input').addEventListener('change',async ev=>{const files=[...ev.target.files];ev.target.value='';try{for(const f of files){if(f.size>12*1024*1024)throw Error('Anlage zu groß (maximal 12 MB).');if(!['image/png','image/jpeg','image/webp','application/pdf'].includes(f.type))throw Error('Bitte PNG, JPG, WebP oder PDF verwenden.');const b=await f.arrayBuffer(),id='asset-'+await HortiImport.hash(b);if(!asset(id)&&!pendingAssets.some(a=>a.id===id))pendingAssets.push({id,name:f.name,mime:f.type,data:HortiImport.base64(b)});modalTask.assetLinks.push({assetId:id,audience:'candidate',caption:f.name});}taskForm();}catch(error){toast(error.message);}});
$('#docx-input').addEventListener('change',async ev=>{const files=[...ev.target.files];ev.target.value='';if(!files.length)return;const specialty=$('#import-fr').value,examType=$('#import-type').value;openModal('Word-Dateien werden eingelesen',`<div class="spinner">${files.length} Datei${files.length>1?'en':''} · Bitte kurz warten …</div>`);try{let next=db,added=0;for(const file of files){const batch=await HortiImport.docx(file,{specialty,examType});if(batch.sources.every(s=>next.sources.some(x=>x.id===s.id)))continue;next=C.merge(next,batch).db;added+=batch.tasks.length;}db=next;changed();closeModal();route='bank';fr=specialty;type=examType;quality='review';query='';render();toast(`${added} Aufgaben eingelesen. Bitte Quellen, Aufteilung, Anlagen und Lösungen prüfen.`);}catch(error){closeModal();toast('Import nicht übernommen: '+error.message);}});
window.addEventListener('beforeunload',ev=>{if(dirty){ev.preventDefault();ev.returnValue='';}});
await initStorage();examId=null;workshopId=isGroup?online.session.meetingId:db.workshops[0]?.id||null;if(isGroup){fr=online.session.specialty;route='group';}if(online){online.onExpired=()=>{clearTimeout(saveTimer);dirty=false;db=null;modalTask=null;pendingAssets=[];proposedTasks=[];};online.onAccess=()=>{if(route==='access'&&!$('#dialog').open)render();};online.onConnectionError=message=>{storageText='Verbindung unterbrochen · '+(dirty?'Änderungen noch nicht gespeichert':'gespeicherten Stand prüfen');const el=$('#save-state');if(el)el.textContent=storageText;};}render();
})();
